(()=>{'use strict';
const C=window.DecisionCore,D=C.D,e=C.esc,app=document.querySelector('#app'),dlg=document.querySelector('#dialog');
if(new URLSearchParams(location.search).get('teacher')==='1'){location.replace(new URL('teacher.html',location.href));return;}
const teacher=false;let s=C.initial(),storageOK=true,reportMode=false,selectedPiece=null,toastTimer,modalReturn=null,galleryState=null;
try{const raw=localStorage.getItem(C.KEY);if(raw)s=C.restore(JSON.parse(raw));}catch(_){storageOK=false;}
const t=(en,zh='')=>`${e(en)}${s.lang==='bi'&&zh?`<span class="zh" lang="zh-Hans">${e(zh)}</span>`:''}`;
const p=v=>t(v.en,v.zh),cur=()=>D.pages.find(x=>x.id===s.slide)||D.pages[0];
const button=(a,label,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${a}" ${attrs}>${label}</button>`;
const ext=(url,label,cls='btn')=>`<a class="${cls}" href="${e(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const guide=id=>D.guides.find(g=>g.id===id)||D.guides[0];
const imageButton=(src,alt,cls='')=>`<button class="image-button ${cls}" data-image="${e(src)}" data-alt="${e(alt)}" type="button"><img src="${e(src)}" alt="${e(alt)}"><span>${t('Enlarge image','放大图片')} ⤢</span></button>`;
function save(kind='update',data={}){window.DecisionTracking?.identify(s);s.updated=new Date().toISOString();try{localStorage.setItem(C.KEY,JSON.stringify(s));}catch(_){storageOK=false;}window.DecisionTracking?.capture(s,kind,data);const el=document.querySelector('#save-status');if(el)el.textContent=s.lang==='bi'?(storageOK?'已保存在此浏览器':'请下载备份'):(storageOK?'Saved in this browser':'Download a backup');}
function toast(en,zh=''){const el=document.querySelector('#toast');el.innerHTML=t(en,zh);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4000);}
function download(name,body,type){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function setHash(){history.replaceState(null,'',location.pathname+location.search+'#'+s.slide);}
function move(id){if(!C.go(s,id,teacher))return;reportMode=false;selectedPiece=null;save();setHash();render(true);}
function header(){return `<header class="topbar"><button class="brand" data-action="home" aria-label="Lesson home"><b>M<span>✦</span></b><span>CS with Mr Dave<small>YEAR 9 · APP STUDIO</small></span></button><div class="top-actions">${teacher?'<span class="teacher-tag">Teacher view</span>':''}<label class="sr-only" for="language">Language / 语言</label><select id="language" aria-label="Language / 语言"><option value="en" ${s.lang==='en'?'selected':''}>English</option><option value="bi" ${s.lang==='bi'?'selected':''}>English + 中文</option></select>${button('guided',t('Extra guidance','更多引导'),s.guided?'selected':'',`aria-pressed="${s.guided}"`)}${button('words',t('Words','词汇'),'quiet')}${button('resources',t('Guides & starter','指南与起始项目'),'quiet')}</div></header>${cloudBar()}`;}
function cloudBar(){return `<div class="school-band"><div><span id="school-save" role="status">${t(s.joined?'Connecting to school…':'School save starts after entry',s.joined?'正在连接学校…':'填写姓名班级后开始学校保存')}</span><button class="text-button" data-action="sharing">${t('What is shared?','会分享哪些内容？')}</button><button id="sync-retry" class="text-button" data-action="sync-retry" hidden>${t('Retry saving','重试保存')}</button><button id="cloud-restore" class="text-button" data-action="cloud-restore" hidden>${t('Restore saved copy','恢复已保存副本')}</button></div>${s.joined?button('help-request',t(s.support.open?'Help requested · cancel':'I need help on this step',s.support.open?'已求助，点击取消':'这一步我需要帮助'),s.support.open?'help-active':'quiet',`aria-pressed="${s.support.open}"`):''}</div>`;}
function banner(){return storageOK?'':`<div class="notice storage-warning">${t('This browser is not saving progress. Download a backup before closing.','此浏览器未能保存进度，请在关闭前下载备份。')} ${button('backup',t('Download backup','下载备份'),'small')}</div>`;}
function landing(){document.title='One Tap, Two Results · Year 9 App Studio';return `${header()}${banner()}<main id="main" class="landing"><section class="hero-copy"><span class="eyebrow">${t('YOUR APP. ONE NEW FEATURE.','你的应用，一个新功能。')}</span><h1>${t('One tap.','一次点击。')}<em>${t('Two possible results.','两种可能的结果。')}</em></h1><p class="lead">${t('Last time, your button showed a message. Today, let a person’s choice decide which message appears.','上次按钮显示一条信息。今天，让用户的选择决定显示哪一条信息。')}</p><div class="outcome-strip"><span><b>01</b>${t('Follow a working decision','跟随能运行的判断')}</span><span><b>02</b>${t('Create your own two responses','设计自己的两种响应')}</span></div><section class="card entry"><h2>${t('Enter your app studio','进入你的应用工作室')}</h2><div class="entry-grid"><label class="field">${t('Your name','你的名字')}<input id="student-name" autocomplete="name" maxlength="90" value="${e(s.student.name)}"></label><label class="field">${t('Class / form','班级')}<select id="student-form"><option value="">${s.lang==='bi'?'Choose / 选择':'Choose your class'}</option>${['9E','9T'].map(x=>`<option value="${x}" ${s.student.form===x?'selected':''}>${x}</option>`).join('')}</select></label></div><p id="join-error" class="field-error" role="alert" hidden></p>${button('join',t(s.visited.length?'Continue my lesson':'Let’s start',s.visited.length?'继续学习':'开始学习')+' →','primary wide')}<p class="small">${t('60 minutes · Two Main Tasks · Short phrases and Mandarin are welcome.','60 分钟 · 两个主任务 · 可以用短语和中文。')}</p>${s.visited.length?button('new',t('Start a new learner record','开始新同学的记录'),'text-button'):''}</section><p class="privacy">${t('Your lesson answers, choices and help requests save to your teacher as you work. Classmates cannot see your responses. No student sign-in or phone is needed.','学习答案、选择和求助会保存给老师，其他同学看不到。不需要学生登录，也不需要手机。')}</p></section><section class="hero-visual" aria-label="An illustrated app with two possible camera information responses"><div class="orbit"></div><div class="hero-app"><span class="eyebrow">FRAME FINDER</span><h2>${t('Choose your view.','选择查看方式。')}</h2><img src="assets/art/camera.svg" alt="Illustrated camera"><div class="hero-choice">Quick summary <span>⌄</span></div><div class="hero-go">Show information</div><div class="hero-result">Compact camera. Easy to carry.</div></div><div class="hero-sticker">${t('Your choice changes the result.','选择改变结果。')}</div><div class="hero-other"><b>More detail</b><p>Zoom lens and a rechargeable battery.</p></div></section><section class="landing-purpose"><b>WAGBA</b><p>${p(D.wagba)}</p><div class="three">${['K','S','U'].map(a=>`<div><strong>${p(D.areas[a])}</strong><p>${p(D.goals[a])}</p></div>`).join('')}</div></section></main>`;}
function rail(){return `<aside class="rail"><details class="purpose" ${window.matchMedia('(max-width: 1000px)').matches?'':'open'}><summary>${t('Today’s WAGBA & KSU','今天的目标与知识技能理解')}</summary><b>WAGBA</b><p>${p(D.wagba)}</p>${['K','S','U'].map(a=>`<section><h2><span>${a}</span>${p(D.areas[a])}</h2><p>${p(D.goals[a])}</p></section>`).join('')}</details><nav aria-label="Lesson stages">${D.groups.map((g,i)=>{const first=D.pages.find(x=>x.group===g.id);return `<button class="stage ${cur().group===g.id?'active':''}" data-go="${first.id}" ${!C.canVisit(s,first.id,teacher)?'disabled':''} ${cur().group===g.id?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${p(g)}<small>${g.minutes} ${t('min','分钟')}</small></span></button>`;}).join('')}</nav><p class="small">${t('One step at a time. Revisit any unlocked stage.','每次专注一步，可以回看已解锁的阶段。')}</p></aside>`;}
function frame(){const pg=cur(),g=D.groups.find(x=>x.id===pg.group),list=D.pages.filter(x=>x.group===pg.group),n=list.findIndex(x=>x.id===pg.id);document.title=pg.title.en+' · Year 9 App Studio';return `${header()}${banner()}<div class="layout">${rail()}<main id="main" class="main" tabindex="-1"><div class="slide-meta"><span>${p(g)}</span><span>${t('Step '+(n+1)+' of '+list.length,'第 '+(n+1)+' 步，共 '+list.length+' 步')}</span></div><div class="step-dots" aria-label="${e(g.en)} steps">${list.map(x=>`<button data-go="${x.id}" class="${x.id===pg.id?'current':s.visited.includes(x.id)?'visited':''}" aria-label="${e(x.title.en)}" ${!C.canVisit(s,x.id,teacher)?'disabled':''} ${x.id===pg.id?'aria-current="step"':''}></button>`).join('')}</div><article class="slide">${pg.type==='learning'?learning(pg):`<h1 id="slide-title">${p(pg.title)}</h1>${body(pg)}`}</article>${teacher?teacherNotes(pg):''}<footer class="slide-footer"><div>${button('back','← '+t('Back','上一步'),'quiet',C.index(s.slide)===0?'disabled':'')}</div><span id="save-status">${t(storageOK?'Saved in this browser':'Download a backup',storageOK?'已保存在此浏览器':'请下载备份')}</span>${C.index(s.slide)<D.pages.length-1?button('next',t('Next step','下一步')+' →','primary'):button('report',t('Preview my PDF','预览我的 PDF'),'primary')}</footer></main></div>`;}
function intro(en,zh){return `<p class="instruction">${t(en,zh)}</p>`;}
function hint(en,zh){return s.guided?`<div class="support"><b>${t('Start here','从这里开始')}</b><p>${t(en,zh)}</p></div>`:'';}
function guideButton(id,label){return `<button class="btn small quiet" data-guide="${id}">${label||t('Show the screenshot guide','查看截图指南')} ⤢</button>`;}
function code(active=null){return `<div class="code-card"><div class="code-caption"><span>${t('Genuine MIT blocks','真实 MIT 积木')}</span>${button('code-zoom',t('Enlarge','放大'),'small quiet')}</div><div class="code-scroll"><div class="block-picture"><img src="assets/blocks/handler.png" alt="When ActionButton.Click: if ChoiceSpinner.Selection equals Quick summary, set ResponseLabel.Text to Compact camera. Easy to carry. Otherwise set it to Zoom lens and a rechargeable battery.">${active?`<span class="code-highlight ${active}" aria-hidden="true"></span>`:''}</div></div></div>`;}
function simulation(x,mode='demo',opts={}){const route=opts.route||'a',selected=opts.selected??(route==='a'?x.choices[0]:x.choices[1]),output=opts.output||'',readonly=opts.readonly,high=opts.high||'';return `<section class="sim ${high}" aria-label="${e(x.title)} classroom simulation"><span class="eyebrow">${t('CLASSROOM SIMULATION','课堂模拟')}</span><h2>${t(x.title,x.zh_title)}</h2><img class="sim-art" src="assets/art/${e(x.image)}.svg" alt="${e(x.title)} illustration"><label class="field sim-input">${t(x.prompt,'选择一个选项')}${readonly?`<span class="static-choice">${t(selected,x.zh_choices[x.choices.indexOf(selected)]||'')}</span>`:`<select data-sim="${mode}" aria-label="${e(mode==='own'?'Your app choice':mode==='gallery'?'Example choice':'Camera information choice')}">${x.choices.map((v,i)=>`<option value="${e(v)}" ${selected===v?'selected':''}>${e(v)}${s.lang==='bi'&&x.zh_choices[i]?' / '+e(x.zh_choices[i]):''}</option>`).join('')}</select>`}</label>${readonly?`<div class="static-go">${t(x.button,x.zh_button)}</div>`:button('sim-run',t(x.button,x.zh_button),'primary wide',`data-mode="${mode}"`)}<div class="sim-output" role="status" aria-live="polite">${output?t(output,x.zh_outputs[x.outputs.indexOf(output)]||''):t('Choose an option, then tap the button.','选择一个选项，再点击按钮。')}</div>${!readonly?button('sim-reset',t('Reset','重置'),'quiet small',`data-mode="${mode}"`):''}<small>${t(mode==='own'?'Preview of your plan; this does not edit your MIT project.':'Sample data. This simulates the starter’s behaviour.',mode==='own'?'这是计划预览，不会修改 MIT 项目。':'使用示例数据，模拟起始项目的行为。')}</small></section>`;}
function demoPage(){const x=D.examples[0];return `${intro('Choose Quick summary, then tap Show information. Try More detail next. Notice which words change.','先选择 Quick summary，再点击 Show information；然后试 More detail，看看哪些文字改变。')}<div class="demo-grid">${simulation(x,'demo',{selected:s.demo.choice,output:s.demo.result})}<div class="response-panel"><span class="eyebrow">${t('CHOOSE → TAP → RESULT','选择 → 点击 → 结果')}</span><h2>${t('What did the app show?','应用显示了什么？')}</h2><div class="result-large" aria-live="polite">${s.demo.result?t(s.demo.result,x.zh_outputs[x.outputs.indexOf(s.demo.result)]):t('Tap the Show button to reveal a result.','点击显示按钮，查看结果。')}</div><div class="seen-row"><span>${s.demo.seen.a?'✓':'○'} Quick summary</span><span>${s.demo.seen.b?'✓':'○'} More detail</span></div><p>${t('Changing the choice clears the old result. Tap the button again to see the new response.','改变选项会清除旧结果；再次点击按钮才会显示新响应。')}</p>${guideButton('check',t('See the two expected results','查看两种预期结果'))}</div></div>`;}
function learning(pg){const c=D.checks.find(x=>x.id===pg.check);return `<section class="learning-card"><span class="area-letter">${c.area}</span><div><span class="eyebrow">${p(D.areas[c.area])}</span><h1 id="slide-title">${p(c.q)}</h1></div></section><p class="instruction">${t('Choose the answer that matches your starting point. New learning is welcome.','选择符合你起点的答案。第一次学习也没关系。')}</p><fieldset class="option-grid"><legend class="sr-only">${p(c.q)}</legend>${D.starting.map(x=>`<label class="option ${s.learning[c.id]===x.id?'selected':''}"><input id="learn-${c.id}-${x.id}" type="radio" name="learning-${c.id}" data-learning="${c.id}" value="${x.id}" ${s.learning[c.id]===x.id?'checked':''}>${p(x)}</label>`).join('')}</fieldset>${s.guided?`<div class="note">${p(c.hint)}</div>`:''}`;}
function focusPage(){const f=C.focus(s);let msg;if(f.winners.length){const areas=f.winners.map(a=>D.areas[a].en).join(' + '),zh=f.winners.map(a=>D.areas[a].zh).join('、');msg=`<h2>${t(f.winners.length===1?'Your main focus: '+areas:'Your focus includes: '+areas,f.winners.length===1?'你的主要重点：'+zh:'你的学习重点包括：'+zh)}</h2><p>${t('These areas have the highest number of “new to me” or “need help” choices ('+f.max+' out of 2). This identifies what to work on; it is not a quiz mark.','这些领域中“第一次学习”或“需要帮助”的数量最多（2 项中有 '+f.max+' 项）。这说明你可以练习什么，不是测验分数。')}</p>${f.winners.map(a=>`<div class="next-action"><strong>${p(D.areas[a])}</strong><p>${p(D.focusActions[a])}</p></div>`).join('')}`;}else msg=`<h2>${t(f.missing===6?'Choose your starting points first.':'Your selected checks are familiar learning.',f.missing===6?'先选择你的学习起点。':'你已选择的内容是熟悉的学习。')}</h2><p>${t(f.missing===6?'The checks have not been answered yet. You can return to them or continue to try the worked example.':'Apply what you know: try the example with less help, then create useful responses for your own app.',f.missing===6?'这些检查尚未回答。可以返回作答，或继续尝试示例。':'运用已有知识：尝试减少提示，再为自己的应用设计有用的响应。')}</p>`;return `<div class="three focus-counts">${['K','S','U'].map(a=>`<section class="card"><span>${a}</span><h2>${p(D.areas[a])}</h2><strong>${f.counts[a]} / 2</strong><p>${t('new / help checks','新内容／需要帮助的项目')}</p><small>${f.secure[a]} ${t('familiar','熟悉')} · ${2-f.selected[a]} ${t('not selected','未选择')}</small></section>`).join('')}</div><section class="card focus-explanation">${msg}</section>${f.missing?`<p class="small">${t(f.missing+' checks are not selected. They are recorded separately, not as wrong.',f.missing+' 项未选择，单独记录，不算错误。')}</p>`:''}`;}
function quiz(pg){const q=D.quiz[pg.quiz],chosen=s.answers[pg.quiz],checked=s.checked[pg.quiz],order=s.orders[pg.quiz];return `${pg.visual==='mini'?`<div class="mini-reference"><img src="assets/art/camera.svg" alt="Camera illustration"><div><b>Frame Finder</b><p>${t('Choice list → Show information → result message','选项列表 → Show information → 结果信息')}</p></div></div>`:''}<fieldset class="quiz-card"><legend>${p(q.q)}</legend><p class="small">${t('Choose one answer, then check it.','选择一个答案，再检查。')}</p><div class="quiz-options">${order.map((id,i)=>{const o=q.options.find(o=>o.id===id);return `<label class="option ${chosen===id?'selected':''}"><input id="quiz-${pg.quiz}-${id}" type="radio" name="quiz-${pg.quiz}" data-quiz="${pg.quiz}" value="${id}" ${chosen===id?'checked':''}><span class="choice-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${p(o)}</span></label>`;}).join('')}</div>${button('check-quiz',t('Check my answer','检查答案'),'primary',`data-quiz="${pg.quiz}" ${!chosen?'disabled':''}`)}${checked?`<div class="feedback" role="status"><strong>${t(chosen===q.correct?'That’s right.':'Let’s look again.',chosen===q.correct?'答对了。':'再看一看。')}</strong><p>${p(q.feedback)}</p></div>`:''}</fieldset>${pg.group==='break'?`<p class="quiet-note">${t('No timer or race. Use the explanation to strengthen your memory.','没有倒计时，也不比速度，用解释帮助记忆。')}</p>`:''}`;}
function trace(pg){const a=pg.route,n=s.trace[a],truth=a==='a',choice=truth?'Quick summary':'More detail',x=D.examples[0],steps=[['Choose '+choice,'选择 '+choice,'The choice supplies the input.','用户的选择提供输入。'],['Tap Show information','点击 Show information','The Click event starts this group of blocks.','Click 事件触发这组积木。'],[truth?'The comparison is TRUE':'The comparison is FALSE',truth?'比较为 TRUE（真）':'比较为 FALSE（假）',truth?'Quick summary matches Quick summary. Follow then.':'More detail does not match Quick summary. Follow else.',truth?'Quick summary 与 Quick summary 匹配，走 then 分支。':'More detail 与 Quick summary 不匹配，走 else 分支。'],['Display the matching message','显示对应的信息',truth?'Only the then message is displayed.':'Only the else message is displayed.',truth?'只显示 then 信息。':'只显示 else 信息。']];const [en,zh,why,whyzh]=steps[n];return `<div class="tutor"><div class="tutor-steps">${steps.map((v,i)=>`<button data-trace="${a}" data-step="${i}" class="${i===n?'active':''}" aria-current="${i===n?'step':'false'}">${i+1}<span>${t(v[0],v[1])}</span></button>`).join('')}</div><div class="tutor-line" aria-live="polite"><span>${n+1}</span><div><h2>${t(en,zh)}</h2><p>${t(why,whyzh)}</p></div></div>${code(n===0?null:n===1?'event':n===2?'condition':truth?'then':'else')}<div class="tutor-bottom"><p>${t('The condition always asks: is ChoiceSpinner.Selection equal to “Quick summary”?','条件始终在问：ChoiceSpinner.Selection 是否等于“Quick summary”？')}</p>${button('tutor-prev','← '+t('Previous explanation','上一个解释'),'quiet',`data-route="${a}" ${n===0?'disabled':''}`)}${button('tutor-next',t(n===3?'Replay the route':'Follow the next step',n===3?'重新跟随':'跟随下一步')+' →','primary',`data-route="${a}"`)}</div><details class="tutor-result" ${n===3?'open':''}><summary>${t('See the app’s result','查看应用结果')}</summary>${simulation(x,'tutor',{readonly:true,selected:choice,output:n===3?x.outputs[truth?0:1]:'',high:n===3?'highlight-output':n===0?'highlight-input':n===1?'highlight-button':''})}</details></div>${!truth?`<div class="note">${t('FALSE means this comparison did not match. It does not mean the user made a mistake.','FALSE 表示这次比较不匹配，不表示用户做错了。')}</div>`:''}`;}
function parsons(){const correct=C.parsonsCorrect(s),parts={condition:t('Condition','条件'),then:t('First response','第一种响应'),else:t('Second response','第二种响应')};return `${intro('Tap a block picture, then tap its destination. You can also drag it. Use the camera example above to help.','先点积木图片，再点目标位置，也可以拖动。可以回看上面的相机示例。')}<p class="piece-status" role="status">${selectedPiece?t('Selected: '+({condition:'condition',then:'first response',else:'second response'})[selectedPiece]+'. Choose a destination.','已选中积木，请选择目标位置。'):t('Choose a picture from the bank.','从图片库选择一块积木。')}</p><div class="parsons-grid"><section class="destinations"><h2>${t('Place the pieces here','把图片放在这里')}</h2>${[['Check the user’s choice','检查用户选择'],['Display this when TRUE','为真时显示'],['Display this when FALSE','为假时显示']].map(([en,zh],i)=>`<button class="destination ${s.parsonsChecked?(correct[i]?'right':'retry'):''}" data-slot="${i}" aria-label="${e('Destination '+(i+1)+': '+en)}"><span class="slot-title"><b>${i+1}</b>${t(en,zh)}</span>${s.parsons[i]?`<img src="assets/blocks/${s.parsons[i]}.png" alt="${e(({condition:'Condition comparing ChoiceSpinner.Selection to Quick summary',then:'Set ResponseLabel.Text to Compact camera. Easy to carry.',else:'Set ResponseLabel.Text to Zoom lens and a rechargeable battery.'})[s.parsons[i]])}"><small>${t('Tap to select this piece and move it.','点击选中这块图片，再移动到其他位置。')}</small>`:`<span class="empty-slot">${t('Tap here after selecting a picture','选中图片后点这里')}</span>`}${s.parsonsChecked?`<small>${t(correct[i]?'This matches.':'Look at this position again.',correct[i]?'匹配正确。':'再看看这个位置。')}</small>`:''}</button>`).join('')}</section><section class="piece-bank"><h2>${t('Block picture bank','积木图片库')}</h2>${s.parsonsOrder.filter(x=>!s.parsons.includes(x)).map(id=>`<button class="piece ${selectedPiece===id?'selected':''}" data-piece="${id}" draggable="true" aria-pressed="${selectedPiece===id}"><img src="assets/blocks/${id}.png" alt="${e(({condition:'Condition comparing the choice with Quick summary',then:'Message: Compact camera. Easy to carry.',else:'Message: Zoom lens and a rechargeable battery.'})[id])}"><span>${t('Tap to select','点击选择')}</span></button>`).join('')||`<p>${t('All pieces are placed. You can select one from a destination to move it.','图片已全部放好，可以点击目标位置中的图片再移动。')}</p>`}</section></div><div class="row">${button('check-parsons',t('Check the arrangement','检查排列'),'primary')}${guideButton('handler',t('Look at the complete example','查看完整示例'))}${button('reset-parsons',t('Return all pictures to the bank','把所有图片放回图片库'),'quiet')}</div>${s.parsonsChecked?`<div class="feedback" role="status">${t(correct.every(Boolean)?'All three jobs match their blocks. You can now follow the input to the correct output.':'Use the comparison for position 1. Then check which message belongs to then and which belongs to else.',correct.every(Boolean)?'三种作用都匹配了，可以从输入跟随到正确输出。':'位置 1 放比较积木，再检查 then 和 else 各自对应哪条信息。')}</div>`:''}`;}
function topicGallery(){return `${intro('Look back at your homepage sketch or PDF from last lesson. Keep your own topic. Explore an example if you need a starting idea.','找出上一课的首页草图或 PDF，保留自己的主题。如果需要起步想法，可以探索示例。')}<div class="own-idea card"><span>✦</span><div><h2>${t('Your idea belongs here.','这里欢迎你自己的创意。')}</h2><p>${t('Music, sport, books, a product, a place, a hobby… choose an appropriate topic you care about.','音乐、运动、书、产品、地点、爱好……选择你关心而且合适的主题。')}</p></div>${button('own-idea',t('Use my own idea','使用自己的创意'),'primary')}</div><div class="gallery">${D.examples.map(x=>`<button class="gallery-card" data-example="${x.id}"><div class="gallery-art"><img src="assets/art/${x.image}.svg" alt="${e(x.title)} illustration"></div><h2>${t(x.title,x.zh_title)}</h2><div class="choice-tags"><span>${t(x.choices[0],x.zh_choices[0])}</span><span>${t(x.choices[1],x.zh_choices[1])}</span></div><small>${t('Try both choices','试试两个选项')} →</small></button>`).join('')}</div>`;}
function field(key,en,zh,{area=false,placeholder='',hintText=''}={}){return `<label class="field"><span>${t(en,zh)}</span>${area?`<textarea id="feature-${key}" data-feature="${key}" rows="3" maxlength="240" placeholder="${e(placeholder)}">${e(s.feature[key])}</textarea>`:`<input id="feature-${key}" data-feature="${key}" maxlength="100" value="${e(s.feature[key])}" placeholder="${e(placeholder)}">`}${hintText?`<small>${e(hintText)}</small>`:''}</label>`;}
function currentExample(){return D.examples.find(x=>x.id===s.feature.example)||D.examples[0];}
function ownData(){return {title:s.feature.name||'My app',zh_title:'',image:s.feature.art,prompt:'Choose',choices:[s.feature.a,s.feature.b],zh_choices:['',''],outputs:[s.feature.outA,s.feature.outB],zh_outputs:['',''],button:s.feature.button,zh_button:''};}
function starterWords(keys){const x=currentExample(),vals={name:x.title,a:x.choices[0],b:x.choices[1],outA:x.outputs[0],outB:x.outputs[1],button:x.button};return `<aside class="starting-words card"><span class="eyebrow">${t('STARTING WORDS','起步文字')}</span><h2>${t(x.title,x.zh_title)}</h2>${keys.map(k=>`<p>${e(vals[k])}${s.lang==='bi'&&['a','b','outA','outB'].includes(k)?`<span class="zh">${e((k==='a'||k==='b'?x.zh_choices:x.zh_outputs)[k==='a'||k==='outA'?0:1])}</span>`:''}</p>`).join('')}${button('fill-empty',t('Use these in empty boxes','用这些文字填写空白框'),'quiet',`data-keys="${keys.join(',')}"`)}<small>${t('These are examples. Change the words to fit your own app.','这些是示例，请按自己的应用修改。')}</small></aside>`;}
function idea(){return `${intro('Use your app idea from the last lesson, or choose something new if you missed it. You are designing one feature, not starting the whole app again.','沿用上一课的应用创意；如果错过了，可以新选主题。现在只设计一个功能，不用重新设计整个应用。')}<div class="form-grid"><div class="card">${field('name','My app’s name','我的应用名称',{placeholder:'e.g. My Music Picks'})}${field('topic','My topic','我的主题',{placeholder:'e.g. music, football, fashion…'})}<label class="field">${t('Picture for the preview','预览图片')}<select id="feature-art" aria-label="Preview picture">${[['camera','Camera / 相机'],['fashion','Fashion / 穿搭'],['gaming','Gaming / 游戏'],['planner','Planner / 计划'],['weather','Weather / 天气'],['booking','Events / 活动']].map(([id,label])=>`<option value="${id}" ${s.feature.art===id?'selected':''}>${e(label)}</option>`).join('')}</select></label><p class="small">${t('The picture is a placeholder for this theory preview. Your topic can be different.','图片只是理论课预览的占位图，主题可以与图片不同。')}</p></div>${starterWords(['name'])}</div>`;}
function choices(){return `${intro('What two options should your user choose between? Give each one a different, clear label.','用户要在哪两个选项之间选择？给它们不同而且清楚的名称。')}<div class="form-grid"><div class="card"><div class="two-fields">${field('a','First choice','第一个选项',{placeholder:'e.g. Calm'})}${field('b','Second choice','第二个选项',{placeholder:'e.g. Energetic'})}</div>${field('button','Words on the Show button','显示按钮上的文字',{placeholder:'e.g. Show a playlist'})}<div class="note">${t('Your condition will check whether the selected choice matches your FIRST choice. If it does not, the second response will appear.','条件会检查用户选择是否与第一个选项匹配；不匹配时显示第二种响应。')}</div></div>${starterWords(['a','b','button'])}</div>${hint('Choose only two options today. “Calm / Energetic” or “Casual / Smart” is enough.','今天只要两个选项，例如“Calm / Energetic”或“Casual / Smart”。')}`;}
function response(pg){const a=pg.route==='a',choice=a?s.feature.a:s.feature.b;return `${intro(a?'What useful message should appear for your first choice? A short phrase or one sentence is enough.':'Now write a different useful message for the second choice.',a?'第一个选项应该显示什么有用信息？短语或一句话就够了。':'现在，为第二个选项写一条不同而且有用的信息。')}<div class="route-banner"><span>${a?'A':'B'}</span><div><small>${t('THE USER CHOOSES','用户选择')}</small><h2>${e(choice|| (a?'First choice':'Second choice'))}</h2></div><span aria-hidden="true">→</span><strong>${t(a?'THEN response':'ELSE response',a?'THEN 响应':'ELSE 响应')}</strong></div><div class="form-grid"><div class="card">${field(a?'outA':'outB',a?'My first response':'My second response',a?'我的第一种响应':'我的第二种响应',{area:true})}<p class="small">${t('Give the information promised by your button. “Button clicked” does not answer the user’s request.','提供按钮承诺的信息。“按钮已点击”没有回答用户的问题。')}</p></div>${starterWords([a?'outA':'outB'])}</div>`;}
function missingList(){const labels={'name':['Give your app a name.','给应用起个名称。'],'choices':['Write two choice labels.','写出两个选项名称。'],'different-choices':['Make the two choice labels different.','让两个选项名称不同。'],'messages':['Write one message for each choice.','为每个选项写一条信息。'],'different-messages':['Make the two responses different.','让两条响应信息不同。'],'button':['Give the Show button a clear label.','为显示按钮写清楚的文字。']};return C.featureIssues(s.feature).map(k=>`<li>${t(...labels[k])}</li>`).join('');}
function preview(){if(!C.ready(s.feature))return `${intro('Return to the named step below to finish your feature. Unfinished work is saved; it is not marked as wrong.','返回下面对应步骤完成内容。未完成的作品会保存，不算错误。')}<div class="card"><ul>${missingList()}</ul><div class="row">${button('edit-idea',t('App name','应用名称'),'quiet')}${button('edit-choices',t('Choices & button','选项与按钮'),'quiet')}${button('edit-a',t('First response','第一种响应'),'quiet')}${button('edit-b',t('Second response','第二种响应'),'quiet')}</div></div>`;return `${intro('Choose an option and tap your button. Try the other choice too. If a message does not help your user, go back and improve that message.','选择一个选项，再点你的按钮，然后试另一个选项。如果信息对用户没帮助，就返回修改那条信息。')}<div class="demo-grid">${simulation(ownData(),'own',{selected:s.preview.choice==='a'?s.feature.a:s.feature.b,output:s.preview.result})}<section class="response-panel"><span class="eyebrow">${t('YOUR INPUT → DECISION → OUTPUT','你的输入 → 判断 → 输出')}</span><h2>${t('One feature. Your own words.','一个功能，用你自己的话。')}</h2><div class="result-large" aria-live="polite">${s.preview.result?e(s.preview.result):t('Your message will appear here after a tap.','点击后，你的信息会显示在这里。')}</div><div class="seen-row"><span>${s.feature.seen.a?'✓':'○'} ${e(s.feature.a)}</span><span>${s.feature.seen.b?'✓':'○'} ${e(s.feature.b)}</span></div><div class="row">${button('edit-a',t('Edit first response','修改第一种响应'),'quiet')}${button('edit-b',t('Edit second response','修改第二种响应'),'quiet')}</div><p class="small">${t('This preview follows your written choices. Your MIT app will be built in the next practical.','预览按照你写的选项运行，MIT 应用会在下一节实践课制作。')}</p></section></div>`;}
function featureCard(){const f=s.feature;return `<section class="feature-card card"><div class="feature-head"><img src="assets/art/${f.art}.svg" alt="Topic illustration"><div><span class="eyebrow">${t('MY NEXT APP FEATURE','我的下一个应用功能')}</span><h2>${e(f.name|| (s.lang==='bi'?'尚未命名':'Name not recorded'))}</h2><p>${e(f.topic||'')}</p></div></div><div class="flow-line"><span>${t('The user chooses','用户选择')}</span><b>${e(f.a||'…')}</b><span>${t('or','或')}</span><b>${e(f.b||'…')}</b><span>→</span><b>${e(f.button||'…')}</b></div><div class="feature-paths"><section><span class="route-tag">TRUE / THEN</span><h3>${t('Choice matches','选项匹配')} “${e(f.a||'…')}”</h3><p class="answer">${e(f.outA|| (s.lang==='bi'?'尚未记录':'Not recorded'))}</p></section><section><span class="route-tag purple">FALSE / ELSE</span><h3>${t('The other choice','另一个选项')} “${e(f.b||'…')}”</h3><p class="answer">${e(f.outB|| (s.lang==='bi'?'尚未记录':'Not recorded'))}</p></section></div><p class="small">${t('Reset returns to the first choice and clears the result.','Reset 返回第一个选项，并清除结果。')}</p></section>`;}
function pit(pg){return `<section class="learning-card"><span class="area-letter">${pg.area}</span><div><span class="eyebrow">${p(D.areas[pg.area])}</span><h2>${p(D.pitQuestions[pg.area])}</h2></div></section>${intro('How is this part of your learning going now? Choose one phase. Each area can be different.','现在这部分学习进行得怎样？选择一个状态，每个领域可以不同。')}<fieldset class="phase-grid"><legend class="sr-only">${p(D.pitQuestions[pg.area])}</legend>${D.phases.map(x=>`<label class="option phase ${s.pit[pg.area]===x.id?'selected':''}"><input id="pit-${pg.area}-${x.id}" name="pit-${pg.area}" data-pit="${pg.area}" value="${x.id}" type="radio" ${s.pit[pg.area]===x.id?'checked':''}><span><strong>${p(x)}</strong><span class="phase-desc">${p(x.desc)}</span></span></label>`).join('')}</fieldset>`;}
function phaseSummary(){const d=C.dominance(Object.values(s.pit));let msg=d.winners.length===1?`${t('Most selected phase'+(d.total<3?' so far':'')+':','选择最多的状态'+(d.total<3?'（目前）':'')+'：')} <strong>${p(D.phases.find(x=>x.id===d.winners[0]))}</strong> (${d.max}/${d.total})`:d.total?t('Your phases are tied. Different areas can need different next steps.','状态数量相同，不同领域可以有不同的下一步。'):t('No phases selected yet.','尚未选择学习状态。');const actions={new:['Keep using the tutor, then try one step without it.','继续用导师示例，再尝试独立完成一步。'],consolidating:['Practise the second route and use your own words for the outputs.','练习第二条分支，并用自己的话写输出。'],water:['Adapt the example to a different topic and justify both responses.','改成不同主题，并说明两种响应的理由。'],drowning:['Ask for help with one named part: the input, comparison or output.','针对一个具体部分求助：输入、比较或输出。']};return `<div class="three">${['K','S','U'].map(a=>`<section class="card"><span class="area-letter small-letter">${a}</span><h2>${p(D.areas[a])}</h2><strong>${s.pit[a]?p(D.phases.find(x=>x.id===s.pit[a])):t('Not selected','未选择')}</strong>${s.pit[a]?`<p>${t(...actions[s.pit[a]])}</p>`:''}</section>`).join('')}</div><div class="feedback phase-summary" role="status"><h2>${msg}</h2><p>${t('This summary comes from your confidence choices, not your quiz score. You can be confident in one area and need help in another.','总结来自你的信心选择，不是测验分数。你可以在一个领域有信心，同时在另一个领域需要帮助。')}</p>${d.total<3?`<p>${t((3-d.total)+' areas are not selected. They are not counted as Drowning.',(3-d.total)+' 个领域未选择，不会算作“感到困难”。')}</p>`:''}</div>`;}
function explain(){const f=s.feature,a=s.explain==='a';return `${intro('Use your own feature to explain one route. Select a choice, then read the sentence aloud or with a partner.','用自己的功能说明一条分支。选一个选项，再自己或与同伴读出句子。')}<div class="card"><label class="field">${t('Which input will you explain?','你要解释哪个输入？')}<select id="explain-route"><option value="a" ${a?'selected':''}>${e(f.a||'First choice')}</option><option value="b" ${!a?'selected':''}>${e(f.b||'Second choice')}</option></select></label><div class="sentence-builder">${t('When the user chooses','当用户选择')} <b>${e((a?f.a:f.b)||'…')}</b>, ${t('and taps','并点击')} <b>${e(f.button||'…')}</b>, ${t('the app shows','应用显示')} <b>${e((a?f.outA:f.outB)||'…')}</b>. <p>${t('The condition asks whether the choice matches','条件检查选项是否匹配')} <b>${e(f.a||'…')}</b>. ${t('Its result is','比较结果为')} <b>${a?'TRUE':'FALSE'}</b>.</p></div>${!C.ready(f)?`<div class="note">${t('Some words are not recorded yet. Return to Main Task 2 to complete them.','有些文字尚未记录，可以返回主任务 2 完成。')}</div>`:''}</div>`;}
function body(pg){switch(pg.type){case 'mission':return `${intro('Keep your app idea from last lesson. Today, design one choice with two useful responses for the person using your app.','保留上一课的应用创意。今天，设计一个选择，为应用用户提供两种有用响应。')}<div class="purpose-card"><b>WAGBA</b><p>${p(D.wagba)}</p></div><div class="two"><section class="card"><span class="task-number">1</span><h2>${t('Follow the decision','跟随判断')}</h2><p>${t('Try a working example. Follow both routes. Place supplied block pictures.','试用示例，跟随两条分支，排列提供的积木图片。')}</p></section><section class="card"><span class="task-number">2</span><h2>${t('Create your two responses','设计你的两种响应')}</h2><p>${t('Choose your own app feature, write two short messages, then try the preview.','选择自己的应用功能，写两条简短信息，再试用预览。')}</p></section></div><div class="note">${t('You will finish with a feature card for the next practical. MIT sign-in is not needed for today’s core theory activities.','完成后会得到下一节实践课使用的功能卡；今天的核心理论活动不需要登录 MIT。')}</div>`;
case 'before':return `${intro('Look at what changed: the button can stay the same, but a choice selects which message appears.','看看变化：按钮可以相同，但选项会决定显示哪条信息。')}${imageButton('assets/guides/step-02.png','Before: one fixed response. Today: Quick summary or More detail leads to a different response.')}`;
case 'quiz':return quiz(pg);case 'focus':return focusPage();case 'demo':return demoPage();
case 'names':return `${intro('These names have different jobs. Changing the words on a button does not rename its component.','这些名称有不同作用。修改按钮上的文字，不会改变组件名。')}<div class="table-wrap"><table><thead><tr><th>${t('What is it?','它是什么？')}</th><th>${t('Example','例子')}</th><th>${t('What it means','意思')}</th></tr></thead><tbody><tr><th>${t('Component name','组件名')}</th><td><code>ActionButton</code></td><td>${t('The program uses this name to find the button.','程序用这个名称找到按钮。')}</td></tr><tr><th>${t('Text property','Text 属性')}</th><td>Show information</td><td>${t('The words the user sees on the button.','用户在按钮上看到的文字。')}</td></tr><tr><th>${t('Separate variable','独立变量')}</th><td><code>current_choice</code> → “Quick summary”</td><td>${t('A named place could store a copy of the choice. It is not used in this core starter.','命名位置可以保存选项的副本；这个核心起始项目没有使用它。')}</td></tr></tbody></table></div><div class="note">${t('This starter reads ChoiceSpinner.Selection directly. That is a component property, not a separate variable named ChoiceSpinner.','起始项目直接读取 ChoiceSpinner.Selection，它是组件属性；ChoiceSpinner 不是另建的变量。')}</div>${guideButton('names')}`;
case 'event':return `${intro('Find “when ActionButton.Click”. This event starts the blocks inside it when the user taps Show information.','找到“when ActionButton.Click”。用户点击 Show information 时，这个事件会触发里面的积木。')}${code('event')}<div class="three compact-cards"><div class="card"><b>1 · ${t('Event','事件')}</b><p>${t('The user taps the button.','用户点击按钮。')}</p></div><div class="card"><b>2 · ${t('Condition','条件')}</b><p>${t('Compare the selected choice with Quick summary.','将用户选择与 Quick summary 比较。')}</p></div><div class="card"><b>3 · ${t('Output','输出')}</b><p>${t('Show one matching message.','显示一条对应信息。')}</p></div></div>`;
case 'trace':return trace(pg);case 'parsons':return parsons();case 'gallery':return topicGallery();case 'idea':return idea();case 'choices':return choices();case 'response':return response(pg);case 'preview':return preview();
case 'feature':return `${intro('This is your feature plan for the next practical. It records what you want to build; the preview has not changed your MIT project.','这是下一节实践课的功能计划，记录你想制作的内容；预览没有修改 MIT 项目。')}${featureCard()}<div class="note">${t('Next practical: use the MyChoice_W10 starter, personalise its appearance, match the first-choice comparison and edit both message blocks. Keep your Week 9 project safe.','下一节实践课：使用 MyChoice_W10 起始项目，修改外观、第一个选项的比较文字和两条信息积木。保留第 9 周项目。')}</div>${guideButton('personalise',t('See where those changes belong in MIT','查看这些修改在 MIT 的哪里'))}`;
case 'challenge':return `${intro('If you have extra time, use one of these challenges. Keep working on the same small feature.','如果还有时间，选择一个挑战，继续完善同一个小功能。')}<div class="two"><section class="card"><span class="eyebrow">${t('THINK FURTHER','进一步思考')}</span><h2>${t('Make the difference useful','让差异更有用')}</h2><p>${t('Read both of your messages. Add one useful detail to each so the two choices clearly serve different needs. Use the preview again.','阅读两条信息，各增加一个有用细节，让两个选项满足不同需求，再试预览。')}</p>${button('edit-a',t('Improve my messages','改进我的信息'),'primary')}</section><section class="card"><span class="eyebrow">${t('READY FOR MIT?','准备好用 MIT？')}</span><h2>${t('Explore the supplied starter','探索提供的起始项目')}</h2><p>${t('Import MyChoice_W10 as a separate study project. Read the same decision in Blocks. Use the guide to find the comparison text. A live device is not required for reading blocks.','把 MyChoice_W10 导入为独立学习项目，在 Blocks 阅读同一个判断。用指南找到比较文字，读积木不需要实际设备。')}</p><a class="btn primary" href="assets/MyChoice_W10.aia" download>${t('Download MIT starter','下载 MIT 起始项目')} ↓</a>${ext('https://login.appinventor.mit.edu/login/',t('Open MIT','打开 MIT'),'btn quiet')}${guideButton('import-menu',t('Follow the import guide','跟随导入指南'))}</section></div>`;
case 'pit':return pit(pg);case 'pit-summary':return phaseSummary();case 'explain':return explain();
case 'finish':return `${intro('Save your feature card and learning record as a PDF. Open the PDF to check it, then attach it to today’s Teams assignment and select Turn in.','把功能卡和学习记录保存成 PDF，打开检查，再附到今天的 Teams 作业中并选择提交。')}<div class="finish-grid"><section class="card save-main"><span class="eyebrow">${t('YOUR MAIN HAND-IN','主要提交文件')}</span><h2>${t('My two-response feature','我的两种响应功能')}</h2><p>${t('Includes your app name, both choices and messages, starting points and learning phases. Unanswered work stays labelled Not recorded.','包含应用名称、两个选项和响应、学习起点与学习状态；未回答内容会标为“尚未记录”。')}</p>${button('pdf',t('Save my PDF','保存我的 PDF')+' ↓','primary large wide')}<p class="small">${t('On iPad: open the print preview, then use Share > Save to Files.','iPad：打开打印预览，再使用“共享 > 存储到文件”。')}</p>${ext('https://teams.microsoft.com/',t('Open Teams','打开 Teams'),'btn quiet')}<p class="small">${t('The app does not upload your work automatically.','应用不会自动上传作品。')}</p></section><section class="card"><h2>${t('Before you submit','提交前')}</h2><ul class="checklist"><li>${s.feature.name.trim()?'✓':'○'} ${t('An app name','应用名称')}</li><li>${s.feature.a.trim()&&s.feature.b.trim()&&s.feature.a.trim().toLowerCase()!==s.feature.b.trim().toLowerCase()?'✓':'○'} ${t('Two different choices','两个不同选项')}</li><li>${s.feature.outA.trim()&&s.feature.outB.trim()&&s.feature.outA.trim()!==s.feature.outB.trim()?'✓':'○'} ${t('Two useful responses','两条有用响应')}</li></ul>${button('edit-choices',t('Return to my feature','返回我的功能'),'quiet')}<details class="backup-tools"><summary>${t('Backup and readable copy','备份与可读副本')}</summary><p>${t('A backup restores this browser lesson. A readable copy opens the record without the activities. Keep the PDF as your main hand-in.','备份可恢复本课网页，可读副本只显示记录，不包含活动；PDF 是主要提交文件。')}</p>${button('backup',t('Download full backup','下载完整备份'),'quiet small')}${button('restore',t('Restore backup','恢复备份'),'quiet small')}${button('readable',t('Download readable copy','下载可读副本'),'quiet small')}</details></section></div>`;
default:return '';}}
function teacherNotes(pg){let text=({read:'Keep the goal to one decision and two useful outputs. No MIT login is required for the core theory route.',now:'Treat these as retrieval, with explanations. Do not infer a confidence phase from correctness.',learning:'Acknowledge existing knowledge. Unselected checks remain separate; new/help choices identify focus, not grades.',main1:'Use both tutor routes. False is a valid comparison result. Parsons: condition, then message, else message. The variable example is conceptual, not an extra required build.',break:'Six questions, no speed ranking. Options shuffle once per notebook and keep their answer IDs.',main2:'Keep student topics open. Model the pattern, then let students supply their own useful content. Starting words fill only empty fields. The browser preview does not modify the .aia.',challenge:'Use this time to improve the feature or inspect the already-tested starter. The final starter imported, saved/reopened and compiled in MIT; live iPad testing is still pending.',pit:'These are student confidence choices, separate for K/S/U. Majority/ties come only from these choices, not quiz marks.',plenary:'Accept a short spoken explanation or Mandarin phrases. The sentence builder uses the learner’s own feature.',finish:'PDF first, then manual Teams submission. Keep JSON restore/readable reports secondary. Lesson responses also save to the protected teacher dashboard.'})[pg.group];if(pg.type==='quiz')text+=' Correct response: '+D.quiz[pg.quiz].options.find(x=>x.id===D.quiz[pg.quiz].correct).en;return `<details class="teacher-notes"><summary>Teacher notes · ${e(pg.group)}</summary><p>${e(text)}</p></details>`;}
function render(scroll=false){app.innerHTML=reportMode?reportHTML():s.joined?frame():landing();window.DecisionTracking?.refresh().catch(()=>{});if(scroll){window.scrollTo({top:0,behavior:'instant'});const el=document.querySelector('#slide-title')||document.querySelector('#main');if(el){el.setAttribute('tabindex','-1');el.focus({preventScroll:true});}}}
function modal(title,body){if(!dlg.open)modalReturn=document.activeElement;dlg.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('close',t('Close','关闭')+' ×','quiet')}</div><div class="dialog-body">${body}</div>`;if(!dlg.open)dlg.showModal();}
function showGuide(id){const g=guide(id);modal(t(g.title,g.zh),`<label class="field">${t('Choose a guide page','选择指南页')}<select id="guide-select">${D.guides.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${x.page}. ${e(x.title)}</option>`).join('')}</select></label><img class="full-guide" src="assets/${g.file}" alt="${e(g.alt_en)}"><p class="small">${t('The screenshot guides show real MIT screens. App-result drawings are labelled as expected results, not live device tests.','截图指南展示真实 MIT 画面；结果示意图已标为预期结果，不是实际设备测试。')}</p>`);}
function resources(){modal(t('Guides and the MIT starter','指南与 MIT 起始项目'),`<div class="resource-list"><a class="resource" href="assets/MyChoice_W10.aia" download><b>${t('Working MIT starter (.aia)','能运行的 MIT 起始项目（.aia）')}</b><span>MyChoice_W10 · ${t('one choice, two outcomes, Reset','一个选择、两种结果、重置')}</span></a><a class="resource" href="assets/Year9_MIT_Choice_Starter_Guide_EN_ZH.pdf" target="_blank" rel="noopener"><b>${t('English–Mandarin screenshot guide','中英文截图指南')}</b><span>24 ${t('focused pages','个重点步骤页')}</span></a><a class="resource" href="assets/Year9_App_Examples_Two_Paths_EN_ZH.pdf" target="_blank" rel="noopener"><b>${t('Six illustrated app examples','六种应用示例图')}</b><span>${t('Both choices and outputs in each example','每种示例都有两个选项和输出')}</span></a></div><div class="row">${guideButton('screens',t('Designer, Blocks or Companion?','Designer、Blocks 还是 Companion？'))}${guideButton('import-menu')}${ext('https://login.appinventor.mit.edu/login/',t('Open MIT school-email login','打开 MIT 学校邮箱登录'))}</div><div class="note">${t('Today’s theory work runs here. MIT is for the extra-time challenge and the next practical. Keep your previous app; import this as a separate study starter.','今天的理论活动在这里完成。MIT 用于有余力时的挑战和下一节实践课。保留旧应用，把这个项目导入为独立学习起始项目。')}</div><p>${t('MIT import, save/reopen and compilation passed. Both paths were checked from the exported blocks. A live iPad Companion check is still pending.','MIT 导入、保存重开和编译通过；两条分支已根据导出的积木检查，实际 iPad Companion 测试尚待进行。')}</p>`);}
function galleryModal(id,keep=false){const x=D.examples.find(x=>x.id===id);if(!keep||!galleryState||galleryState.id!==id)galleryState={id,choice:x.choices[0],result:''};const i=D.examples.indexOf(x);modal(t(x.title,x.zh_title),`<div class="gallery-modal-grid">${simulation(x,'gallery',{selected:galleryState.choice,output:galleryState.result})}<div><h2>${t('Try both choices. What changes?','试试两个选项，什么改变了？')}</h2><p>${t('The user’s choice changes the response. Borrow the pattern and keep your own topic.','用户的选择改变响应。可以借鉴方式，同时保留自己的主题。')}</p>${button('use-example',t('Use this example’s starting words','使用这个示例的起步文字'),'primary',`data-id="${x.id}"`)}<p class="small">${t('Only empty boxes will be filled. Your existing words are kept.','只填写空白框，保留已有文字。')}</p>${imageButton('assets/example-'+(i+1)+'.png',x.title+' illustrated two-choice example')}</div></div>`);}
function reportHTML(){const f=C.focus(s),phase=C.dominance(Object.values(s.pit)),answered=Object.keys(s.answers).length,checked=Object.keys(s.checked).length;return `<div class="report-actions">${button('print',t('Print / Save PDF','打印／保存 PDF'),'primary')}${button('return',t('Return to lesson','返回课程'),'quiet')}</div><main id="main" class="report-sheet"><span class="eyebrow">YEAR 9 · APP DEVELOPMENT THEORY</span><h1>${t('My two-response app feature','我的两种响应应用功能')}</h1><p><b>${e(s.student.name)}</b> · ${e(s.student.form)}<br>${new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kuala_Lumpur',dateStyle:'long'}).format(new Date())}</p><section class="report-block"><b>WAGBA</b><p>${p(D.wagba)}</p></section>${featureCard()}<p>${t('This is a feature plan and browser simulation record. It does not certify that an MIT app has been built or tested on a device.','这是一份功能计划和浏览器模拟记录，不证明 MIT 应用已制作或在设备上测试。')}</p><h2>${t('Preview record','预览记录')}</h2><p>${t('First choice tried: '+(s.feature.seen.a?'Yes':'Not tried yet')+'. Second choice tried: '+(s.feature.seen.b?'Yes':'Not tried yet')+'.','第一个选项：'+(s.feature.seen.a?'已尝试':'尚未尝试')+'；第二个选项：'+(s.feature.seen.b?'已尝试':'尚未尝试')+'。')}</p><h2>${t('My starting points','我的学习起点')}</h2><table><tbody>${D.checks.map(c=>`<tr><td>${c.area} · ${p(c.q)}</td><td>${s.learning[c.id]?p(D.starting.find(x=>x.id===s.learning[c.id])):t('Not selected','未选择')}</td></tr>`).join('')}</tbody></table><p>${t('New/help counts: Knowledge '+f.counts.K+', Skills '+f.counts.S+', Understanding '+f.counts.U+'. '+f.missing+' checks not selected.','新内容／需要帮助：知识 '+f.counts.K+'，技能 '+f.counts.S+'，理解 '+f.counts.U+'；未选择 '+f.missing+' 项。')}</p><h2>${t('Learning Pit Stop','学习加油站')}</h2><table><tbody>${['K','S','U'].map(a=>`<tr><th>${p(D.areas[a])}</th><td>${s.pit[a]?p(D.phases.find(x=>x.id===s.pit[a])):t('Not selected','未选择')}</td></tr>`).join('')}</tbody></table><p>${t(phase.winners.length===1?'Most selected confidence phase: '+D.phases.find(x=>x.id===phase.winners[0]).en+' ('+phase.max+'/'+phase.total+').':'No single most-selected phase. Areas can differ.',phase.winners.length===1?'选择最多的信心状态：'+D.phases.find(x=>x.id===phase.winners[0]).zh+'（'+phase.max+'/'+phase.total+'）。':'没有单一主要状态，不同领域可以不同。')}</p><h2>${t('Block-picture arrangement','积木图片排列')}</h2><p>${s.parsons.map((v,i)=>`${i+1}: ${v?e(v):t('Not placed','未放置')}`).join(' · ')}</p><p>${t(s.parsonsChecked?'Arrangement checked against the model.':'Arrangement not checked yet.',s.parsonsChecked?'已对照示例检查排列。':'尚未检查排列。')}</p><h2>${t('Retrieval checks','知识回顾检查')}</h2><p>${answered}/${Object.keys(D.quiz).length} ${t('answered','已回答')} · ${checked} ${t('checked with feedback','已检查并查看反馈')}</p>${Object.entries(D.quiz).map(([id,q])=>`<section class="report-block"><b>${p(q.q)}</b><p>${s.answers[id]?p(q.options.find(x=>x.id===s.answers[id])):t('Not attempted','尚未尝试')}${s.checked[id]?' · '+t(s.answers[id]===q.correct?'Correct when checked':'Reviewed with feedback',s.answers[id]===q.correct?'检查时正确':'已查看反馈'):''}</p></section>`).join('')}<h2>${t('Next practical','下一节实践课')}</h2><p>${t('Use the MyChoice_W10 starter. Personalise the title and picture, enter two choices, match the comparison to the first choice and replace the two message blocks with your feature’s words. Save and export the .aia.','使用 MyChoice_W10 起始项目，修改名称和图片，输入两个选项，让比较文字匹配第一个选项，再用自己的两条信息替换对应积木。保存并导出 .aia。')}</p></main>`;}
function showReport(print=false){save('export',{format:'pdf'});window.DecisionTracking?.flush();reportMode=true;document.title=(s.feature.name||s.student.name||'Year 9')+' - App Feature Record';render(true);if(print)Promise.all([document.fonts.ready,...[...document.images].map(im=>im.decode().catch(()=>{}))]).then(()=>requestAnimationFrame(()=>window.print()));}
function backup(){const state={...s};delete state.trackingId;download('Year9-App-Decisions-Backup.json',JSON.stringify({kind:'year9-app-decisions',version:1,state},null,2),'application/json');toast('Backup downloaded. Keep it before changing devices.','备份已下载，更换设备前请保留。');}
function readable(){const base=location.href,css=`@font-face{font-family:Raleway;src:url('${new URL('assets/raleway.ttf?v=20261026-1',base)}');font-weight:400;font-display:swap}@font-face{font-family:Raleway;src:url('${new URL('assets/raleway-bold.ttf?v=20261026-1',base)}');font-weight:700;font-display:swap}body{font:18px/1.6 Raleway,Arial,'PingFang SC',sans-serif;margin:35px;color:#193d32}.report-sheet{max-width:950px;margin:auto}.report-actions{display:none}.zh{display:block;font-size:.9em;font-family:'PingFang SC','Microsoft YaHei',sans-serif}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aab8aa;padding:12px;text-align:left}img{max-width:100%;width:100px}.feature-paths{display:grid;grid-template-columns:1fr 1fr;gap:20px}.feature-card,.report-block{border:1px solid #ccd6c9;padding:18px;margin:20px 0}.answer{white-space:pre-wrap;overflow-wrap:anywhere}@media print{@page{size:A4;margin:16mm}body{font-size:11pt;margin:0}tr,.feature-card,.report-block{break-inside:avoid}}`;const body=reportHTML().replace(/src="assets\//g,'src="'+new URL('assets/',base).href);download('Year9-App-Feature-Readable.html','<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My app feature</title><style>'+css+'</style><body>'+body+'</body></html>','text/html');}
async function action(el){const a=el.dataset.action;switch(a){case 'join':{const name=document.querySelector('#student-name').value.trim(),form=document.querySelector('#student-form').value.trim().toUpperCase();if(name.length<2||!['9E','9T'].includes(form)){const er=document.querySelector('#join-error');er.hidden=false;er.innerHTML=t('Enter your name (at least two characters) and choose 9E or 9T.','请输入至少两个字的姓名，并选择 9E 或 9T。');document.querySelector(name.length<2?'#student-name':'#student-form').focus();return;}if(s.visited.length&&(s.student.name!==name||s.student.form!==form)&&!(s.student.name===name&&!s.trackingId&&!['9E','9T'].includes(s.student.form))){if(!confirm(s.lang==='bi'?'姓名或班级改变会开启新的学习记录。需要保留作品时，请先下载备份。继续？':'A different name or class starts a new learner record. Download a backup first if you need this work. Continue?'))return;const lang=s.lang;s=C.initial();s.lang=lang;window.DecisionTracking?.stop();}s.student={name:name.slice(0,90),form:form.slice(0,35)};s.joined=true;if(!s.visited.includes(s.slide))s.visited.push(s.slide);setHash();save();render(true);break;}
case 'new':if(confirm(s.lang==='bi'?'下载备份后再开始新记录。替换此浏览器中的当前记录？':'Download a backup first if needed. Replace the current browser record with a new learner record?')){const lang=s.lang;s=C.initial();s.lang=lang;window.DecisionTracking?.stop();save();history.replaceState(null,'',location.pathname+location.search);render(true);}break;
case 'home':s.joined=false;save();window.DecisionTracking?.stop();render(true);break;
case 'guided':s.guided=!s.guided;save();render(false);break;
case 'next':if(C.advance(s)){setHash();save();render(true);}break;
case 'back':{const i=C.index(s.slide);if(i>0)move(D.pages[i-1].id);break;}
case 'sharing':modal(t('Your lesson work and your teacher','你的学习作品与老师'),`<p>${t('Your teacher can see the answers you choose, the messages you write for your app, your progress, your KSU reflections and help requests. Other students cannot open your record.','老师可以看到选择的答案、应用信息、进度、知识技能理解反思和求助。其他同学不能打开你的记录。')}</p><p>${t('Changes save after a short pause. Look for “Saved to teacher”. Offline changes stay on this device and retry when the connection returns. Only work inside this lesson is shared.','暂停输入后会保存，请查看“已保存给老师”。离线更改留在设备中，连接恢复后重试。只分享本课中的作品。')}</p>${window.DecisionTracking?.details().error?`<p class="notice">${e(window.DecisionTracking.details().error)}</p>`:''}`);break;
case 'sync-retry':await window.DecisionTracking?.retry(s);break;
case 'cloud-restore':await window.DecisionTracking?.restoreSaved();break;
case 'help-request':s.support={open:!s.support.open,at:new Date().toISOString(),page:s.slide};save(s.support.open?'support':'support-clear');render(false);toast(s.support.open?'Help request queued. Look for “Saved to teacher”. For help now, use your classroom signal.':'Help request cancelled.',s.support.open?'求助等待保存，请查看“已保存给老师”。需要即时帮助时请举手。':'已取消求助。');break;
case 'words':modal(t('Words for today','今天的词汇'),`<div class="glossary">${D.glossary.map(([en,zh,def,dzh])=>`<section><h3>${t(en,zh)}</h3><p>${t(def,dzh)}</p></section>`).join('')}</div>`);break;
case 'resources':resources();break;case 'close':dlg.close();modalReturn?.focus?.();break;
case 'code-zoom':modal(t('Read the MIT handler','阅读 MIT 事件程序'),`<img class="full-code" src="assets/blocks/handler.png" alt="Complete MIT if/else handler"><div class="note">${t('If the selected choice is Quick summary, the then message runs. Otherwise, the else message runs.','如果选中 Quick summary，就执行 then 信息，否则执行 else 信息。')}</div>`);break;
case 'check-quiz':if(s.answers[el.dataset.quiz]){s.checked[el.dataset.quiz]=true;save('quiz-check',{question:el.dataset.quiz,answer:s.answers[el.dataset.quiz]});render(false);}break;
case 'sim-run':{const mode=el.dataset.mode;if(mode==='demo'){s.demo.result=s.demo.choice===D.examples[0].choices[0]?D.examples[0].outputs[0]:D.examples[0].outputs[1];s.demo.seen[s.demo.choice===D.examples[0].choices[0]?'a':'b']=true;save();render(false);}else if(mode==='gallery'){const x=D.examples.find(x=>x.id===galleryState.id);galleryState.result=x.outputs[x.choices.indexOf(galleryState.choice)];galleryModal(x.id,true);}else if(mode==='own'){const r=C.result(s.feature,s.preview.choice);if(r!==null){s.preview.result=r;s.feature.seen[s.preview.choice]=true;save('preview',{choice:s.preview.choice,output:s.preview.result});render(false);}}break;}
case 'sim-reset':if(el.dataset.mode==='gallery'){galleryState.choice=D.examples.find(x=>x.id===galleryState.id).choices[0];galleryState.result='';galleryModal(galleryState.id,true);}else if(el.dataset.mode==='demo'){s.demo.choice='Quick summary';s.demo.result='';save();render(false);}else{s.preview={choice:'a',result:''};save();render(false);}break;
case 'tutor-prev':s.trace[el.dataset.route]=Math.max(0,s.trace[el.dataset.route]-1);save();render(false);break;
case 'tutor-next':s.trace[el.dataset.route]=(s.trace[el.dataset.route]+1)%4;save();render(false);break;
case 'check-parsons':s.parsonsChecked=true;save('parsons-check');render(false);break;
case 'reset-parsons':s.parsons=[null,null,null];s.parsonsChecked=false;selectedPiece=null;save();render(false);break;
case 'own-idea':if(cur().id==='gallery'){C.advance(s);setHash();save();render(true);}else move('idea');break;
case 'use-example':C.seed(s,el.dataset.id);save();dlg.close();toast('Starting words filled empty boxes. You can change them.','已用起步文字填写空白框，可以继续修改。');render(false);break;
case 'fill-empty':{const x=currentExample(),vals={name:x.title,a:x.choices[0],b:x.choices[1],outA:x.outputs[0],outB:x.outputs[1],button:x.button};for(const k of el.dataset.keys.split(','))if(!s.feature[k].trim())C.updateFeature(s,k,vals[k]);save();render(false);toast('Only empty boxes were filled. Make the words your own.','只填写了空白框，请按自己的想法修改。');break;}
case 'edit-idea':move('idea');break;case 'edit-choices':move('choices');break;case 'edit-a':move('response-a');break;case 'edit-b':move('response-b');break;
case 'pdf':showReport(true);break;case 'report':showReport();break;case 'print':window.print();break;case 'return':reportMode=false;s.joined=true;s.slide='finish';save();render(true);break;case 'backup':backup();break;case 'readable':readable();break;case 'restore':document.querySelector('#backup-file').click();break;
}}
document.addEventListener('click',ev=>{const go=ev.target.closest('[data-go]');if(go){move(go.dataset.go);return;}const g=ev.target.closest('[data-guide]');if(g){showGuide(g.dataset.guide);return;}const im=ev.target.closest('[data-image]');if(im){modal(e(im.dataset.alt),`<img class="full-guide" src="${e(im.dataset.image)}" alt="${e(im.dataset.alt)}">`);return;}const ex=ev.target.closest('[data-example]');if(ex){galleryModal(ex.dataset.example);return;}const tr=ev.target.closest('[data-trace]');if(tr){s.trace[tr.dataset.trace]=Number(tr.dataset.step);save();render(false);return;}const piece=ev.target.closest('[data-piece]');if(piece){selectedPiece=piece.dataset.piece;render(false);return;}const slot=ev.target.closest('[data-slot]');if(slot){const i=Number(slot.dataset.slot);if(selectedPiece){C.place(s,selectedPiece,i);selectedPiece=null;save();render(false);}else if(s.parsons[i]){selectedPiece=s.parsons[i];render(false);}else toast('Select a block picture first, then its destination.','先选中积木图片，再选择目标位置。');return;}const el=ev.target.closest('[data-action]');if(el)action(el).catch(err=>toast('This action could not finish. Your work is still on this page.','这次操作未完成，作品仍保留在当前页面。'));});
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.feature){C.updateFeature(s,el.dataset.feature,el.value);save();}});
document.addEventListener('change',async ev=>{const el=ev.target;let focusId=el.id;if(el.id==='student-form'){return;}else if(el.id==='language'){s.lang=el.value==='bi'?'bi':'en';save();render(false);}else if(el.dataset.quiz){s.answers[el.dataset.quiz]=el.value;delete s.checked[el.dataset.quiz];save();render(false);}else if(el.dataset.learning){s.learning[el.dataset.learning]=el.value;save();render(false);}else if(el.dataset.pit){s.pit[el.dataset.pit]=el.value;save();render(false);}else if(el.dataset.sim){const mode=el.dataset.sim;if(mode==='gallery'){galleryState.choice=el.value;galleryState.result='';galleryModal(galleryState.id,true);}else if(mode==='demo'){s.demo.choice=el.value;s.demo.result='';save();render(false);}else{s.preview.choice=el.value===s.feature.b?'b':'a';s.preview.result='';save();render(false);}}else if(el.id==='feature-art'){s.feature.art=el.value;save();}else if(el.id==='guide-select'){showGuide(el.value);}else if(el.id==='explain-route'){s.explain=el.value;save();render(false);}else if(el.id==='backup-file'){const f=el.files[0];if(!f)return;try{if(f.size>1000000)throw Error('Backup too large');const raw=JSON.parse(await f.text());if(raw.kind!=='year9-app-decisions'||raw.version!==1)throw Error('Wrong lesson');const incoming=C.restore({...raw.state,trackingId:''});if(incoming.student.name===s.student.name&&incoming.student.form===s.student.form)incoming.trackingId=s.trackingId;if(!confirm(s.lang==='bi'?'用备份替换当前记录？如需保留当前作品，请先下载备份。':'Replace this record with the backup? Download your current backup first if needed.'))return;window.DecisionTracking?.stop();s=incoming;save('restore');setHash();render(true);toast('Backup restored.','备份已恢复。');}catch(_){toast('Choose a valid backup from this lesson. The current record was kept.','请选择本课的有效备份，当前记录已保留。');}finally{el.value='';}}if(focusId&&document.getElementById(focusId))document.getElementById(focusId).focus({preventScroll:true});});
document.addEventListener('dragstart',ev=>{const el=ev.target.closest('[data-piece]');if(el){selectedPiece=el.dataset.piece;ev.dataTransfer.setData('text/plain',selectedPiece);ev.dataTransfer.effectAllowed='move';}});document.addEventListener('dragover',ev=>{if(ev.target.closest('[data-slot]'))ev.preventDefault();});document.addEventListener('drop',ev=>{const el=ev.target.closest('[data-slot]');if(!el)return;ev.preventDefault();const v=ev.dataTransfer.getData('text/plain');if(C.place(s,v,Number(el.dataset.slot))){selectedPiece=null;save();render(false);}});
dlg.addEventListener('click',ev=>{if(ev.target===dlg)dlg.close();});dlg.addEventListener('close',()=>{modalReturn?.focus?.();});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(s.joined&&C.canVisit(s,id,teacher)){move(id);}});
window.DecisionTracking?.onRestore(incoming=>{incoming.orders=s.orders;incoming.parsonsOrder=s.parsonsOrder;s=C.restore(incoming);s.joined=true;save('restore');setHash();render(true);});
s.student.form=s.student.form.trim().toUpperCase().replace(/^YEAR\s*/, '').replace(/\s+/g,'');
if(s.joined){if(s.student.name.trim().length<2||!['9E','9T'].includes(s.student.form)){s.joined=false;}else save('resume');}
const requested=location.hash.slice(1);if(s.joined&&C.canVisit(s,requested,teacher))C.go(s,requested,teacher);render();
})();
